from __future__ import annotations

from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .choice_delta_function_call import ChoiceDeltaFunctionCall, ChoiceDeltaFunctionCallDict
from .choice_delta_tool_call import ChoiceDeltaToolCall, ChoiceDeltaToolCallDict
from .enums.role import RoleOrStr


class ChoiceDelta(SdkBaseModel):
    """A chat completion delta generated by streamed model responses."""

    content: Optional[str] = UNSET
    function_call: Optional[ChoiceDeltaFunctionCall] = UNSET
    refusal: Optional[str] = UNSET
    role: Optional[RoleOrStr] = UNSET
    tool_calls: Optional[list[ChoiceDeltaToolCall]] = UNSET


class ChoiceDeltaDict(TypedDict):
    content: NotRequired[str]
    function_call: NotRequired[ChoiceDeltaFunctionCallDict]
    refusal: NotRequired[str]
    role: NotRequired[RoleOrStr]
    tool_calls: NotRequired[list[ChoiceDeltaToolCallDict]]
